pub enum Expr { Num(i64), Add(Box<Expr>, Box<Expr>) }
impl Expr {
    pub fn eval(&self, ctx: &Context) -> Result<i64, EvalError> {
        match self {
            Expr::Num(n) => Ok(*n),
            Expr::Add(l, r) => {
                let (l, r) = (l.eval(ctx)?, r.eval(ctx)?);
                l.checked_add(r).ok_or(EvalError::Overflow)
            }
        }
    }
}

